/**
 * Dirty tracker: records which floor meshes need to be rebuilt by the 3D engine.
 * The renderer reads and clears these flags each frame.
 */

const dirtySet = new Set<string>();

export function markDirty(floorId: string): void {
  dirtySet.add(floorId);
}

export function markAllDirty(floorIds: string[]): void {
  for (const id of floorIds) {
    dirtySet.add(id);
  }
}

export function isDirty(floorId: string): boolean {
  return dirtySet.has(floorId);
}

export function consumeDirty(): Set<string> {
  const snapshot = new Set(dirtySet);
  dirtySet.clear();
  return snapshot;
}

export function clearDirty(floorId: string): void {
  dirtySet.delete(floorId);
}
