import { memo } from 'react';
import type { BoxSelectState } from '../../types/editor';
import { COLORS } from '../../utils/constants';

interface SelectionOverlayProps {
  boxSelectState: BoxSelectState;
}

export const SelectionOverlay = memo(function SelectionOverlay({ boxSelectState }: SelectionOverlayProps) {
  if (!boxSelectState?.active) return null;

  const x = Math.min(boxSelectState.startX, boxSelectState.endX);
  const y = Math.min(boxSelectState.startY, boxSelectState.endY);
  const w = Math.abs(boxSelectState.endX - boxSelectState.startX);
  const h = Math.abs(boxSelectState.endY - boxSelectState.startY);

  return (
    <rect x={x} y={y} width={w} height={h}
      fill={COLORS.selectionFill} stroke={COLORS.selection}
      strokeWidth={0.03} strokeDasharray="0.1 0.05" />
  );
});
