import type { CSSProperties } from 'react';
import { useStore } from '../../store';

export function UndoRedoButtons() {
  const undo = useStore(s => s.undo);
  const redo = useStore(s => s.redo);
  const canUndoVal = useStore(s => s.canUndo());
  const canRedoVal = useStore(s => s.canRedo());

  const btnStyle = (enabled: boolean): CSSProperties => ({
    width: 36,
    height: 36,
    border: 'none',
    borderRadius: 6,
    background: 'transparent',
    color: enabled ? '#334155' : '#cbd5e1',
    fontSize: 16,
    cursor: enabled ? 'pointer' : 'default',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
  });

  return (
    <div style={{ display: 'flex', gap: 2 }}>
      <button onClick={undo} disabled={!canUndoVal} style={btnStyle(canUndoVal)} title="Undo">
        ↩
      </button>
      <button onClick={redo} disabled={!canRedoVal} style={btnStyle(canRedoVal)} title="Redo">
        ↪
      </button>
    </div>
  );
}
