import { produceWithPatches, applyPatches, enablePatches } from 'immer';
import type { Command, CommandEntry, CommandStack } from '../types/command';
import type { Project } from '../types/project';

enablePatches();

export function createCommandStack(): CommandStack {
  return { entries: [], currentIndex: -1 };
}

export interface CommandResult {
  nextProject: Project;
  nextStack: CommandStack;
}

export function executeCommand(
  stack: CommandStack,
  command: Command,
  project: Project,
): CommandResult {
  const [nextProject, patches, inversePatches] = produceWithPatches(
    project,
    (draft) => { command.execute(draft as Project); },
  );

  const entry: CommandEntry = { command, patches, inversePatches };

  // Truncate redo branch
  const entries = [...stack.entries.slice(0, stack.currentIndex + 1), entry];

  return {
    nextProject: nextProject as Project,
    nextStack: { entries, currentIndex: entries.length - 1 },
  };
}

export function undoCommand(
  stack: CommandStack,
  project: Project,
): CommandResult | null {
  if (!canUndo(stack)) return null;

  const entry = stack.entries[stack.currentIndex]!;
  const nextProject = applyPatches(project, entry.inversePatches) as Project;

  return {
    nextProject,
    nextStack: { ...stack, currentIndex: stack.currentIndex - 1 },
  };
}

export function redoCommand(
  stack: CommandStack,
  project: Project,
): CommandResult | null {
  if (!canRedo(stack)) return null;

  const entry = stack.entries[stack.currentIndex + 1]!;
  const nextProject = applyPatches(project, entry.patches) as Project;

  return {
    nextProject,
    nextStack: { ...stack, currentIndex: stack.currentIndex + 1 },
  };
}



export function squashCommandEntries(
  stack: CommandStack,
  startIndex: number,
  endIndex: number,
  command: Command,
): CommandStack {
  if (startIndex < 0 || endIndex < startIndex || endIndex >= stack.entries.length) return stack;

  const targetEntries = stack.entries.slice(startIndex, endIndex + 1);
  if (!targetEntries.length) return stack;

  const patches = targetEntries.flatMap((entry) => entry.patches);
  const inversePatches = [...targetEntries].reverse().flatMap((entry) => entry.inversePatches);
  const mergedEntry: CommandEntry = { command, patches, inversePatches };

  const entries = [
    ...stack.entries.slice(0, startIndex),
    mergedEntry,
    ...stack.entries.slice(endIndex + 1),
  ];

  const removedCount = endIndex - startIndex;
  let currentIndex = stack.currentIndex;
  if (currentIndex >= startIndex && currentIndex <= endIndex) {
    currentIndex = startIndex;
  } else if (currentIndex > endIndex) {
    currentIndex -= removedCount;
  }

  return { entries, currentIndex };
}

export function canUndo(stack: CommandStack): boolean {
  return stack.currentIndex >= 0;
}

export function canRedo(stack: CommandStack): boolean {
  return stack.currentIndex < stack.entries.length - 1;
}
