import { create } from 'zustand';
import { createProjectSlice, type ProjectSlice } from './project-slice';
import { createEditorSlice, type EditorSlice } from './editor-slice';
import { createUISlice, type UISlice } from './ui-slice';

export type AppState = ProjectSlice & EditorSlice & UISlice;

export const useStore = create<AppState>()((set, get, api) => ({
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  ...createProjectSlice(set as any, get as any, api as any),
  ...createEditorSlice(set as any, get as any, api as any),
  ...createUISlice(set as any, get as any, api as any),
}));

// Convenience hooks
export const useProject = () => useStore((s) => s.project);
export const useActiveFloorId = () => useStore((s) => s.activeFloorId);
export const useActiveTool = () => useStore((s) => s.activeTool);
export const useSelection = () => useStore((s) => s.selection);
export const useViewMode = () => useStore((s) => s.viewMode);
