import { useStore } from '../../store';
import { createAddFloorCommand } from '../../engine/commands';
import { createId } from '../../utils/id';
import { DEFAULT_FLOOR_HEIGHT } from '../../utils/constants';

export function FloorSelector() {
  const project = useStore(s => s.project);
  const activeFloorId = useStore(s => s.activeFloorId);
  const setActiveFloor = useStore(s => s.setActiveFloor);
  const applyCommand = useStore(s => s.applyCommand);

  const addFloor = () => {
    const maxZ = project.floors.reduce((max, f) => Math.max(max, f.z + f.height), 0);
    const newFloor = {
      id: createId(),
      name: `${project.floors.length + 1}F`,
      z: maxZ,
      height: DEFAULT_FLOOR_HEIGHT,
    };
    applyCommand(createAddFloorCommand(newFloor));
    setActiveFloor(newFloor.id);
  };

  return (
    <div style={{
      display: 'flex',
      alignItems: 'center',
      gap: 2,
      overflowX: 'auto',
      WebkitOverflowScrolling: 'touch',
      padding: '0 4px',
      flex: 1,
    }}>
      {project.floors.map(floor => (
        <button
          key={floor.id}
          onClick={() => setActiveFloor(floor.id)}
          style={{
            padding: '6px 14px',
            border: 'none',
            borderRadius: 6,
            background: activeFloorId === floor.id ? '#2563eb' : '#f1f5f9',
            color: activeFloorId === floor.id ? 'white' : '#334155',
            fontSize: 13,
            fontWeight: activeFloorId === floor.id ? 600 : 400,
            cursor: 'pointer',
            whiteSpace: 'nowrap',
            flexShrink: 0,
          }}
        >
          {floor.name}
        </button>
      ))}
      <button
        onClick={addFloor}
        style={{
          width: 32,
          height: 32,
          border: '1px dashed #94a3b8',
          borderRadius: 6,
          background: 'transparent',
          color: '#64748b',
          fontSize: 18,
          cursor: 'pointer',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          flexShrink: 0,
        }}
        title="Add Floor"
      >
        +
      </button>
    </div>
  );
}
