import type { Command } from '../../types/command';
import type { Floor, WalkNode, WalkEdge } from '../../types/project';
import type { Item } from '../../types/item';

export function createAddFloorCommand(floor: Floor): Command {
  return {
    type: 'addFloor',
    description: `Add floor ${floor.name}`,
    execute(project) {
      project.floors.push(floor);
      return project;
    },
  };
}

export function createDeleteFloorCommand(floorId: string): Command {
  return {
    type: 'deleteFloor',
    description: `Delete floor`,
    execute(project) {
      project.floors = project.floors.filter(f => f.id !== floorId);
      project.nodes = project.nodes.filter(n => n.floorId !== floorId);
      const nodeIds = new Set(project.nodes.map(n => n.id));
      project.links = project.links.filter(e => nodeIds.has(e.from) && nodeIds.has(e.to));
      project.items = project.items.filter(i => i.floorId !== floorId);
      return project;
    },
  };
}

export function createAddNodeCommand(node: WalkNode): Command {
  return {
    type: 'addNode',
    description: `Add node`,
    execute(project) {
      project.nodes.push(node);
      return project;
    },
  };
}

export function createDeleteNodeCommand(nodeId: string): Command {
  return {
    type: 'deleteNode',
    description: `Delete node`,
    execute(project) {
      project.nodes = project.nodes.filter(n => n.id !== nodeId);
      project.links = project.links.filter(e => e.from !== nodeId && e.to !== nodeId);
      return project;
    },
  };
}

export function createAddEdgeCommand(edge: WalkEdge): Command {
  return {
    type: 'addEdge',
    description: `Add edge`,
    execute(project) {
      project.links.push(edge);
      return project;
    },
  };
}

export function createDeleteEdgeCommand(edgeId: string): Command {
  return {
    type: 'deleteEdge',
    description: `Delete edge`,
    execute(project) {
      project.links = project.links.filter(e => e.id !== edgeId);
      return project;
    },
  };
}

export function createMoveNodeCommand(nodeId: string, newX: number, newY: number): Command {
  return {
    type: 'moveNode',
    description: `Move node`,
    execute(project) {
      const node = project.nodes.find(n => n.id === nodeId);
      if (node) { node.x = newX; node.y = newY; }
      return project;
    },
  };
}

export function createAddItemCommand(item: Item): Command {
  return {
    type: 'addItem',
    description: `Add ${item.type} item`,
    execute(project) {
      project.items.push(item);
      return project;
    },
  };
}

export function createDeleteItemCommand(itemId: string): Command {
  return {
    type: 'deleteItem',
    description: `Delete item`,
    execute(project) {
      project.items = project.items.filter(i => i.id !== itemId);
      return project;
    },
  };
}

export function createMoveSelectionCommand(nodeIds: string[], dx: number, dy: number): Command {
  return {
    type: 'moveSelection',
    description: `Move ${nodeIds.length} nodes`,
    execute(project) {
      const idSet = new Set(nodeIds);
      for (const node of project.nodes) {
        if (idSet.has(node.id)) {
          node.x += dx;
          node.y += dy;
        }
      }
      return project;
    },
  };
}

export function createDeleteSelectionCommand(nodeIds: string[], edgeIds: string[]): Command {
  return {
    type: 'deleteSelection',
    description: `Delete selection`,
    execute(project) {
      const nodeIdSet = new Set(nodeIds);
      const edgeIdSet = new Set(edgeIds);
      project.nodes = project.nodes.filter(n => !nodeIdSet.has(n.id));
      // Also remove edges connected to deleted nodes
      const allDeletedNodeIds = new Set([
        ...nodeIds,
        ...project.nodes.filter(n => nodeIdSet.has(n.id)).map(n => n.id),
      ]);
      project.links = project.links.filter(
        e => !edgeIdSet.has(e.id) && !allDeletedNodeIds.has(e.from) && !allDeletedNodeIds.has(e.to),
      );
      return project;
    },
  };
}
