import { useStore } from '../../store';
import type { EditorTool } from '../../types/editor';

const tools: Array<{ id: EditorTool; label: string; icon: string }> = [
  { id: 'select', label: 'Select', icon: '👆' },
  { id: 'addNode', label: 'Node', icon: '⊕' },
  { id: 'drawEdge', label: 'Edge', icon: '╱' },
  { id: 'addItem', label: 'Item', icon: '▤' },
  { id: 'pan', label: 'Pan', icon: '✋' },
];

export function Toolbar() {
  const activeTool = useStore(s => s.activeTool);
  const setTool = useStore(s => s.setTool);
  const viewMode = useStore(s => s.viewMode);

  if (viewMode === '3d') return null;

  return (
    <div style={{
      position: 'absolute',
      bottom: 16,
      left: '50%',
      transform: 'translateX(-50%)',
      display: 'flex',
      gap: 4,
      background: 'white',
      borderRadius: 12,
      padding: 4,
      boxShadow: '0 2px 12px rgba(0,0,0,0.15)',
      zIndex: 10,
    }}>
      {tools.map(tool => (
        <button
          key={tool.id}
          onClick={() => setTool(tool.id)}
          style={{
            width: 48,
            height: 48,
            border: 'none',
            borderRadius: 8,
            background: activeTool === tool.id ? '#2563eb' : 'transparent',
            color: activeTool === tool.id ? 'white' : '#475569',
            fontSize: 18,
            cursor: 'pointer',
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            justifyContent: 'center',
            padding: 0,
          }}
          title={tool.label}
        >
          <span style={{ fontSize: 20 }}>{tool.icon}</span>
          <span style={{ fontSize: 8, marginTop: 1 }}>{tool.label}</span>
        </button>
      ))}
    </div>
  );
}
