import type { StateCreator } from 'zustand';
import { enablePatches } from 'immer';
import type { Project, WalkNode, WalkEdge, Item } from '../types';
import type { Command, CommandStack } from '../types/command';
import { createCommandStack, executeCommand, undoCommand, redoCommand, canUndo, canRedo, squashCommandEntries } from '../engine/command-manager';
import { markAllDirty } from '../engine/dirty-tracker';
import { createId } from '../utils/id';
import { DEFAULT_GRID, DEFAULT_FLOOR_HEIGHT } from '../utils/constants';

enablePatches();

export interface ProjectSlice {
  project: Project;
  commandStack: CommandStack;

  // Actions
  setProject: (project: Project) => void;
  applyCommand: (command: Command) => void;
  undo: () => void;
  redo: () => void;
  canUndo: () => boolean;
  canRedo: () => boolean;
  groupCommands: (startIndex: number, endIndex: number, description: string, type?: Command['type']) => void;

  // Derived selectors (as functions)
  getFloorNodes: (floorId: string) => WalkNode[];
  getFloorEdges: (floorId: string) => WalkEdge[];
  getFloorItems: (floorId: string) => Item[];
}

export function createDefaultProject(): Project {
  const floorId = createId();
  return {
    id: createId(),
    version: '0.1',
    name: 'New Project',
    grid: { ...DEFAULT_GRID },
    floors: [{ id: floorId, name: '1F', z: 0, height: DEFAULT_FLOOR_HEIGHT }],
    nodes: [],
    links: [],
    items: [],
    constraints: [],
    updatedAt: Date.now(),
  };
}

export const createProjectSlice: StateCreator<ProjectSlice & Record<string, unknown>, [], [], ProjectSlice> = (set, get) => ({
  project: createDefaultProject(),
  commandStack: createCommandStack(),

  setProject: (project) => set({ project, commandStack: createCommandStack() }),

  applyCommand: (command) => {
    const state = get();
    const result = executeCommand(state.commandStack, command, state.project);

    // Mark affected floors as dirty for 3D rebuild
    const allFloorIds = result.nextProject.floors.map((f) => f.id);
    markAllDirty(allFloorIds);

    set({
      project: { ...result.nextProject, updatedAt: Date.now() },
      commandStack: result.nextStack,
    });
  },

  undo: () => {
    const state = get();
    const result = undoCommand(state.commandStack, state.project);
    if (result) {
      markAllDirty(result.nextProject.floors.map((f) => f.id));
      set({ project: result.nextProject, commandStack: result.nextStack });
    }
  },

  redo: () => {
    const state = get();
    const result = redoCommand(state.commandStack, state.project);
    if (result) {
      markAllDirty(result.nextProject.floors.map((f) => f.id));
      set({ project: result.nextProject, commandStack: result.nextStack });
    }
  },

  canUndo: () => canUndo(get().commandStack),
  canRedo: () => canRedo(get().commandStack),

  groupCommands: (startIndex, endIndex, description, type = 'batch') => {
    const state = get();
    const command: Command = {
      type,
      description,
      execute: (project) => project,
    };
    const nextStack = squashCommandEntries(state.commandStack, startIndex, endIndex, command);
    if (nextStack !== state.commandStack) {
      set({ commandStack: nextStack });
    }
  },

  getFloorNodes: (floorId) => get().project.nodes.filter((n) => n.floorId === floorId),
  getFloorEdges: (floorId) => {
    const nodeIds = new Set(
      get().project.nodes.filter((n) => n.floorId === floorId).map((n) => n.id),
    );
    return get().project.links.filter((e) => nodeIds.has(e.from) || nodeIds.has(e.to));
  },
  getFloorItems: (floorId) => get().project.items.filter((i) => i.floorId === floorId),
});
