import { useStore } from '../../store';
import type { ItemPlacementType } from '../../types/editor';

const itemTypes: Array<{ id: ItemPlacementType; label: string; icon: string }> = [
  { id: 'stairs', label: 'Stairs', icon: '🪜' },
  { id: 'elevator', label: 'Elevator', icon: '🛗' },
];

export function ItemPalette() {
  const activeTool = useStore(s => s.activeTool);
  const itemPlacementType = useStore(s => s.itemPlacementType);
  const setItemPlacementType = useStore(s => s.setItemPlacementType);

  if (activeTool !== 'addItem') return null;

  return (
    <div style={{
      position: 'absolute',
      bottom: 80,
      left: '50%',
      transform: 'translateX(-50%)',
      display: 'flex',
      gap: 4,
      background: 'white',
      borderRadius: 8,
      padding: 4,
      boxShadow: '0 2px 12px rgba(0,0,0,0.15)',
      zIndex: 10,
    }}>
      {itemTypes.map(item => (
        <button
          key={item.id}
          onClick={() => setItemPlacementType(item.id)}
          style={{
            padding: '8px 14px',
            border: 'none',
            borderRadius: 6,
            background: itemPlacementType === item.id ? '#2563eb' : 'transparent',
            color: itemPlacementType === item.id ? 'white' : '#475569',
            fontSize: 13,
            cursor: 'pointer',
            display: 'flex',
            alignItems: 'center',
            gap: 4,
          }}
        >
          <span>{item.icon}</span>
          <span>{item.label}</span>
        </button>
      ))}
    </div>
  );
}
