import { openDB, type IDBPDatabase } from 'idb';
import type { Project } from '../types';

const DB_NAME = 'sketch3d-db';
const DB_VERSION = 1;
const STORE_NAME = 'projects';

async function getDB(): Promise<IDBPDatabase> {
  return openDB(DB_NAME, DB_VERSION, {
    upgrade(db) {
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME, { keyPath: 'id' });
      }
    },
  });
}

export async function saveProject(project: Project): Promise<void> {
  const db = await getDB();
  await db.put(STORE_NAME, { ...project, updatedAt: Date.now() });
}

export async function loadProject(id: string): Promise<Project | null> {
  const db = await getDB();
  const result = await db.get(STORE_NAME, id);
  return result ?? null;
}

export async function listProjects(): Promise<Array<{ id: string; name: string; updatedAt: number }>> {
  const db = await getDB();
  const all = await db.getAll(STORE_NAME);
  return all.map((p: any) => ({ id: p.id, name: p.name, updatedAt: p.updatedAt }));
}

export async function deleteProject(id: string): Promise<void> {
  const db = await getDB();
  await db.delete(STORE_NAME, id);
}
