import type { Point } from '@/types';

export function distance(a: Point, b: Point): number {
  return Math.sqrt((a.x - b.x) ** 2 + (a.y - b.y) ** 2);
}

export function clamp(value: number, min: number, max: number): number {
  return Math.min(Math.max(value, min), max);
}

export function lerp(a: number, b: number, t: number): number {
  return a + (b - a) * t;
}

export function snapToGrid(value: number, gridSize: number): number {
  return Math.round(value / gridSize) * gridSize;
}

export function snapPointToGrid(point: Point, gridSize: number): Point {
  return {
    x: snapToGrid(point.x, gridSize),
    y: snapToGrid(point.y, gridSize),
  };
}

export function angleBetween(from: Point, to: Point): number {
  return Math.atan2(to.y - from.y, to.x - from.x) * (180 / Math.PI);
}

export function snapAngle(angleDeg: number, stepDeg: number): number {
  return Math.round(angleDeg / stepDeg) * stepDeg;
}

export function polarToCartesian(origin: Point, angleDeg: number, dist: number): Point {
  const rad = angleDeg * (Math.PI / 180);
  return { x: origin.x + Math.cos(rad) * dist, y: origin.y + Math.sin(rad) * dist };
}
